P.QBANK = ["ماذا تُظهر لي هذه الآية عن شخص الله؟","أي طبيعة قديمة أنانية تكشفها هذه الآية في داخلي؟","لو تركتُ يسوع يملك في هذا الموقف، فماذا سأفعل؟","أي مثال يُريني إياه يسوع هنا؟","ما الخطوة التي يقودني الروح القدس إلى أن أخطوها اليوم؟","لماذا أخفق الناس في هذه الآية؟ هل السبب الكبرياء أم الخوف؟","كيف تساعدني هذه الآية على ممارسة حياة إنكار الذات (Wu Ji)؟","في أي علاقة ينبغي أن أطبّق هذه الآية؟","ما صلة هذه الآية بعبارة «ليأتِ ملكوتك» في الصلاة الربانية؟","أعطني صورة من الحياة اليومية تكشف جوهر هذه الآية."];
P.QAUD = {"seeker":["ما صلة هذا المقطع بحياتي الآن؟","لستُ مسيحيًا. ماذا تعني لي هذه الكلمات؟","هل الله موجود؟ وما أسباب الإيمان؟","لماذا يقول الكتاب المقدس إن الجميع يحتاجون إلى يسوع؟","أمرّ بضغوط كثيرة. ما العون العملي الذي يقدّمه الكتاب المقدس؟","ماذا تعني «الخطية» هنا؟ وهل لها علاقة بي؟","كثيرًا ما يتحدث المسيحيون عن «النعمة». ماذا تعني بلغة بسيطة؟","إن أردتُ أن أعرف أكثر، فمن أين أبدأ؟"],"teen":["ما صلة هذا المقطع بحياتي اليومية: المدرسة والأصدقاء والهاتف؟","لو كان هذا المقطع رسالة من الله لي أنا خاصةً، فماذا يقول لي؟","الجميع يفعلون ذلك. هل من الغريب ألّا أفعل مثلهم؟ وماذا يقول الكتاب المقدس؟","هل يمكنك أن تشرح هذا المقطع بمثال من لعبة أو فيلم؟","ما الشيء المفاجئ أو القليل المعرفة في هذا المقطع؟","ضغط الامتحانات كبير. ما القوة التي يمنحني إياها هذا المقطع؟","لا أستطيع أن أسامح شخصًا. كيف يساعدني هذا المقطع؟","هل يراني الله حقًا؟ وما الذي يجعلني أستحق المحبة؟"],"kid":["عمَّ تحكي هذه القصة؟ احكِها لي من فضلك.","ماذا فعل الله في هذه القصة؟","هل يحبني يسوع؟ كيف أعرف ذلك؟","من هو الأشجع في هذه القصة؟ ولماذا؟","كيف أصبح مثل الأشخاص في هذه القصة؟","علّمني آية قصيرة لأتذكرها.","تخاصمتُ للتو مع صديقي المقرّب. ماذا كان يسوع سيفعل؟","هل يمكنك أن تعلّمني صلاة صغيرة؟"]};
P.AUD2 = {"elder":{"q":["بأبسط الكلمات، ماذا يقول هذا المقطع؟","كيف يعزّي هذا المقطع كبار السن؟","جسدي يضعف شيئًا فشيئًا. كيف يعتني الله بي؟","كثيرًا ما أشعر بالوحدة. ماذا يعطيني هذا المقطع؟","كيف أورّث الإيمان لأبنائي وأحفادي؟","هناك أمور لا أستطيع التخلي عنها بعد. كيف يعلّمني هذا المقطع أن أسلّمها للرب؟","لقد كبرتُ في السن. ماذا يمكنني بعدُ أن أفعله من أجل الله؟","من فضلك اكتب لي صلاة قصيرة أرفعها إلى الرب."],"fu":["الصحة","الوحدة","العائلة","التسليم","الرجاء","الصلاة"],"rw":["لقد أتممتَ قراءة سفر {nm} كاملًا!","يومًا بعد يوم وصلتَ إلى هنا. الله يذكر هذه الأمانة، وهي قدوة لنا نحن الأصغر سنًّا."],"res":["لا بأس، على مهلك. إعادة القراءة ستجعل المعنى أوضح.","أحسنت! تتذكر الكثير من هذا الإصحاح.","رائع! كلمة الله حيّة في قلبك."]},"single_parent":{"q":["أربّي أولادي وحدي. كيف يعزّيني هذا المقطع؟","أنا مرهق جدًّا وأشعر بأنني مقصّر تجاه أولادي. كيف ينظر الله إليّ؟","كيف يهتم الله بالأيتام والأرامل، وماذا يعني ذلك لي؟","المال شحيح جدًّا. ماذا يمنحني هذا المقطع؟","ابني يجادلني وانفعالاته شديدة. ماذا ينبغي أن أفعل؟","لا أعرف كيف أحدّث ابني عن الأب (أو الأم) الغائب عنا.","أشعر بوحدة شديدة. كيف أطلب العون من الكنيسة أو من إخوتي في الإيمان؟","من فضلك اكتب لي صلاة قصيرة أستطيع أن أصلّيها في خمس دقائق."],"fu":["الإرهاق","الأولاد","المال","طلب العون","الرجاء","الصلاة"],"rw":["لقد أتممتَ قراءة سفر {nm} كاملًا!","المداومة على قراءة الكتاب المقدس وأنت تحمل أسرتك وحدك ليست أمرًا هيّنًا. الله يرى كل خطوة تخطوها، وهو معك."],"res":["لا بأس، فقد بذلتَ جهدًا كبيرًا. عُد إلى القراءة حين يتسع وقتك.","أحسنت! حتى في هذا الانشغال تتذكر الكثير.","رائع! كلمة الله تسندك."]},"single":{"q":["بصفتي غير متزوج، ماذا يقول لي هذا المقطع؟","أشعر بالوحدة. ماذا يعطيني هذا المقطع؟","من أنا في المسيح، وما قيمتي؟","كيف أثق بالله وأنا في الانتظار؟","ما الحكمة التي يقدّمها الكتاب المقدس عن العلاقات؟","كيف يمكن تقديم وقت غير المتزوج وطاقته لله؟","كيف أبني علاقات طيبة في الكنيسة ومع الأصدقاء؟","من فضلك اكتب صلاة قصيرة لشخص غير متزوج."],"fu":["الوحدة","الهوية","الانتظار","العلاقات","غاية الحياة","الصلاة"],"rw":["لقد أتممتَ قراءة سفر {nm} كاملًا!","تواصل السير بثبات وحدك، وأمام الله أيامك كاملة ومحبوبة."],"res":["لا بأس، على مهلك. إعادة القراءة ستجعل المعنى أوضح.","أحسنت! لقد أدركتَ جوهر هذا الإصحاح.","ممتاز! أنت مجتهد، وكلمة الله تتأصل فيك."]},"parent":{"q":["ماذا يذكّرني به هذا المقطع بصفتي أبًا أو أمًّا؟","ابني لا يريد أن يسمع الكلام وانفعالاته شديدة. كيف ينبغي أن أتصرف؟","كيف أوازن بين التأديب والنعمة؟","كيف أتحاور جيدًا مع ابني المراهق؟","كثيرًا ما أغضب من ابني ثم أشعر بالذنب. ماذا أفعل الآن؟","كيف أقود ابني إلى معرفة الله، لا إلى مجرد الذهاب إلى الكنيسة؟","أنا وشريك حياتي نختلف في طريقة تربية الأولاد. ماذا يقول هذا المقطع؟","من فضلك اكتب صلاة بركة قصيرة لابني."],"fu":["الحوار","التأديب","الشعور بالذنب","شريك الحياة","الإيمان","الصلاة"],"rw":["لقد أتممتَ قراءة سفر {nm} كاملًا!","في خضم مشاغل تربية الأولاد تواظب على قراءة الكتاب المقدس كل يوم. وهذه أفضل قدوة تقدّمها لهم."],"res":["لا بأس، على مهلك. عُد إلى القراءة حين تتاح لك الفرصة.","أحسنت! لقد أدركتَ جوهر هذا الإصحاح.","رائع! كلمة الله تتأصل في بيتك."]},"couple":{"q":["ماذا يقول لنا هذا المقطع بصفتنا زوجًا وزوجة؟","بعد كل خلاف نبرد تجاه بعضنا. كيف يمكن لأحدنا أن يبادر بالخطوة الأولى نحو المصالحة؟","كيف أعبّر عمّا في قلبي ليسمعه شريك حياتي؟","شريك حياتي جرح مشاعري. هل يجب عليّ حقًا أن أسامحه؟","نختلف في أمور المال والأعمال المنزلية. ماذا ينبغي أن نفعل؟","كيف نصلّي معًا ونقترب إلى الله معًا؟","ضغوط الحياة تباعد بيننا. كيف نعود قريبين؟","من فضلك اكتب صلاة بركة قصيرة لزواجنا."],"fu":["الحوار","المسامحة","الألفة","وحدة القلب","القراءة معًا","الصلاة"],"rw":["لقد أتممتما قراءة سفر {nm} كاملًا معًا!","الزوجان اللذان يقتربان معًا إلى كلمة الله يقفان على أساس راسخ."],"res":["لا بأس، على مهلكما. في إحدى الأمسيات القادمة أعيدا القراءة معًا.","أحسنتما! لقد أدركتما جوهر هذا الإصحاح.","رائع! كلمة الله تتأصل في زواجكما."]},"pastor":{"q":["ماذا يقول لي هذا المقطع في الخدمة؟","ساعدني من فضلك في إيجاد مخطط عظة ونقطة انطلاق لهذا المقطع.","أنا منهَك وعلى وشك الإنهاك التام. كيف يعزّيني هذا المقطع؟","كيف أواجه النقد وسوء الفهم في الكنيسة؟","ماذا يقول هذا المقطع عن قيادة فريق متحد القلب؟","وسط الخدمة المزدحمة، كيف أحفظ مسيرتي الشخصية مع الله؟","كيف أرعى الضعفاء والجرحى ومن تركوا الكنيسة؟","من فضلك اكتب صلاة شفاعة قصيرة من أجل الكنيسة وزملائي في الخدمة."],"fu":["العظة","الرعاية","الفريق","الراحة","الحرب الروحية","الشفاعة"],"rw":["لقد أتممتَ قراءة سفر {nm} كاملًا!","البقاء قريبًا من كلمة الله وسط الخدمة المزدحمة هو أعمق جذور الرعاية."],"res":["لا بأس، على مهلك. عُد إلى القراءة حين تتاح لك الفرصة.","أحسنت! لقد أدركتَ جوهر هذا الإصحاح.","رائع! كلمة الله تُطعم الراعي أولًا، ثم تفيض على القطيع."]}};
