P.Q20 = {"adult":["أقساط البيت والرسوم المدرسية تُثقل كاهلي. ما الرجاء الذي يعطيه لي هذا المقطع؟","أعمل بجدّ لكنني كثيرًا ما أشعر بالفراغ. لماذا؟","أنا وزوجي (أو زوجتي) في خصام صامت منذ أيام. ما أول ما يطلبه مني هذا المقطع؟","لا أستطيع أن أسامح من جرحني. كيف يساعدني يسوع على التخلّي عن هذا الجرح؟","لستُ متأكدًا من وجود الله. ما الأسباب التي تدعو إلى الإيمان؟","لماذا يتألم الأخيار أيضًا؟ أين الله؟","أؤمن منذ سنوات، لكن صلاتي تبدو كأنني أحدّث نفسي. ماذا أفعل؟","لماذا كان لا بدّ أن يموت يسوع على الصليب؟ وما علاقة ذلك بي؟","ارتكبتُ أخطاءً في ماضيّ. هل ما زال الله يقبلني؟","ابني (أو ابنتي) متمرّد. كيف أستخدم هذا المقطع لأسير معه؟","عند فقدان العمل أو فشل المشروع، كيف يواصل الذين يتّكلون على يسوع مسيرتهم؟","والداي كبيران في السنّ ومريضان وأنا منهك. كيف يعزّيني هذا المقطع؟","أشعر بالقلق ولا أستطيع النوم. ما هو السلام الذي يتحدث عنه يسوع؟","كيف أحدّث أهلي أو زملائي غير المؤمنين عن يسوع دون أن أنفّرهم؟","أريد أن أتبع يسوع لكنني أخشى سخرية أهلي أو معارضتهم. ماذا أفعل؟","ما الفرق بين الإيمان بيسوع وعبادة آلهة أخرى، أو مجرّد أن يكون المرء إنسانًا صالحًا؟","كيف يبدأ المرء في التعرّف إلى يسوع؟ وما الخطوة الصغيرة التي أستطيع اتخاذها اليوم؟","أغضب بسرعة ولا أستطيع التخلّص من عاداتي السيئة. هل يستطيع يسوع حقًّا أن يغيّر الإنسان؟","أخاف من الموت. ماذا يقصد يسوع بالحياة الأبدية؟","إن أردتُ أن أسلّم حياتي ليسوع اليوم، فكيف أصلّي؟"],"teen":["ما علاقة هذا المقطع بحياتي في المدرسة؟","ضغط الامتحانات هائل. هل تبقى لي قيمة إن كانت درجاتي سيئة؟","لكل واحد شلّته وأنا أشعر بأنني مُبعَد. كيف ينظر يسوع إليّ؟","أتعرّض للتنمّر (أو خانني صديق) وأنا غاضب جدًّا. ماذا كان يسوع سيفعل؟","أشعر بأنني لستُ جميلًا أو جيّدًا بما يكفي. هل يحبّني الله فعلًا؟","أهلي يتشاجرون دائمًا (أو يتحكّمون بي أكثر من اللازم) وقد ضقتُ ذرعًا. ماذا يقول الكتاب المقدس؟","أصدقائي يقولون إن المسيحية خرافة وإن العلم هو الصواب. كيف أردّ عليهم؟","أُعجبتُ بشخص ما. هل يجوز أن أدخل في علاقة عاطفية؟ وما الحكمة التي يقدّمها الكتاب المقدس؟","لا أستطيع التوقف عن تصفّح الهاتف أو لعب الألعاب الإلكترونية. ماذا أفعل؟","لماذا أؤمن بيسوع أصلًا؟ وماذا لو لم أؤمن؟","هل كان يسوع شخصًا حقيقيًّا؟ وما الدليل على ذلك؟","ارتكبتُ خطأً وأخاف أن أخبر أحدًا. هل سيغفر لي الله؟","كثيرًا ما أشعر بالقلق والحزن. هل يستطيع يسوع أن يكون معي؟","الجميع يقول «كن على طبيعتك». هل اتّباع يسوع يعني أن أفقد حريتي؟","إن كان الله يحبّني، فلماذا يسمح بحدوث أمور محزنة لي؟","أريد أصدقاء حقيقيين. كيف يعلّمني يسوع أن أكون صديقًا صالحًا؟","إن أردتُ أن أتبع يسوع، فماذا أفعل أولًا؟ وهل يجب أن أكون كاملًا؟","هل الصلاة تنفع حقًّا؟ وهل يمكنني أن أكلّم الله بكلماتي الخاصة؟","لا أعرف ماذا أدرس أو أي عمل سأمتهن لاحقًا. كيف أواجه المستقبل؟","كيف أشرح لأصدقائي بكلماتي من هو يسوع؟"],"kid":["عن ماذا تحكي هذه القصة؟ هل تحكيها لي؟","من هو يسوع؟ وأين يسكن؟","هل يحبّني يسوع فعلًا؟ كيف أعرف ذلك؟","أين الله؟ أنا لا أراه، فكيف يسمعني؟","فعلتُ شيئًا خاطئًا فغضب ماما وبابا. هل يغضب يسوع مني أيضًا؟","تخاصمتُ مع صديقي المفضّل. ماذا كان يسوع سيفعل؟","أخاف من الظلام ومن الأحلام المزعجة. هل يستطيع يسوع أن يحرسني؟","الواجب المدرسي صعب جدًّا ولا أريد الذهاب إلى المدرسة. هل يستطيع يسوع أن يساعدني؟","لماذا مات يسوع على الصليب؟","لماذا عاد يسوع إلى الحياة بعدما مات؟","جدّتي مريضة (أو جروي مريض). هل سيشفيها يسوع؟","كيف هي السماء؟","هناك ولد في المدرسة يعاملني بقسوة. ماذا أفعل؟ وماذا يقول يسوع؟","هل تعلّمني كيف أصلّي؟ ماذا أقول؟","من خلق الله؟","هل يمكن أن يكون يسوع أعزّ أصدقائي؟ كيف؟","كيف أتعلّم أن أتشارك مع الأطفال الآخرين بفرح؟","ما هي «الخطية»؟ هل عندي خطية أنا أيضًا؟","علّمني آية قصيرة أستطيع أن أحفظها.","أريد أن يسكن يسوع في قلبي. ماذا أقول؟"],"seeker":["لم أقرأ الكتاب المقدس من قبل. ما علاقة هذا المقطع بحياتي الآن؟","هل الله موجود فعلًا؟ ما الأسباب التي تدعو إلى الإيمان؟","لماذا يوجد كل هذا الألم في العالم؟ لماذا لا يوقفه الله؟","ألم يكتب البشرُ الكتابَ المقدس؟ لماذا يمكنني أن أثق به؟","هل وُجد يسوع فعلًا؟ وما الذي يميّزه؟","أرى أنني إنسان صالح. فلماذا أحتاج إلى يسوع مع ذلك؟","أليست كل الأديان تعلّم الناس فعل الخير؟ ما الذي يميّز المسيحية؟","أنا تحت ضغط شديد وأشعر بالفراغ. ما العون العملي الذي يستطيع الكتاب المقدس أن يقدّمه لي؟","فعلتُ أمورًا سيئة جدًّا. هل يقبل الله إنسانًا مثلي؟","أهلي يكرّمون الأجداد (أو يتبعون ديانة أخرى). هل الإيمان بيسوع إساءة إليهم، أو قد يؤدي إلى رفضهم لي؟","هل يتعارض العلم مع الإيمان؟","سمعتُ أن اتّباع يسوع يعني التخلّي عن كثير من الفرح. هل هذا صحيح؟","لماذا كان لا بدّ أن يموت يسوع؟ وما علاقة موته بي؟","هل القيامة حقيقية؟ وعلى ماذا تستند؟","التقيتُ بمنافقين في الكنيسة وهذا يجعلني أتردّد. كيف أنظر إلى ذلك؟","ماذا يعني «الإيمان بيسوع»؟ هل يجب أن أفهم كل شيء، أو أن أُصلح حياتي أولًا؟","حياتي جيدة بدون إيمان. فماذا سأكسب إن آمنتُ بيسوع؟","أودّ أن أتعرّف إلى يسوع بنفسي. كيف أبدأ بقراءة الكتاب المقدس؟","إن قرّرتُ أن أؤمن بيسوع، فما الخطوة الأولى؟ وكيف أصلّي؟","ما زالت لدي أسئلة كثيرة. هل يمكنني أن أسأل وأنا أتقدّم، وأقرّر ببطء؟"],"elder":["أنا متقدّم في السن وأعاني آلامًا كثيرة. كيف يعزّيني هذا المقطع؟","أولادي مشغولون وأشعر بالوحدة. كيف يرافقني يسوع؟","أخاف من الموت ومن المكان الذي سأذهب إليه. ماذا يقول يسوع؟","رحل شريك حياتي وقلبي فارغ. ما العزاء الذي يقدّمه الكتاب المقدس؟","عبدتُ الأصنام والأجداد طوال حياتي. هل فات الأوان على أن أؤمن بيسوع الآن؟","أولادي وأحفادي لا يؤمنون. ماذا أستطيع أن أفعل من أجلهم؟","فعلتُ في شبابي أمورًا أندم عليها. هل سيغفر لي الله؟","بصري ضعيف ولا أستطيع القراءة جيدًا. كيف أستمع إلى الكتاب المقدس وأصلّي؟","في هذا العمر، ما معنى الحياة؟ وماذا يريد الله مني بعد؟","كثيرًا ما أعجز عن النوم وتتسارع أفكاري. هل يستطيع يسوع أن يمنحني السلام؟","أولادي لا يعاملونني بلطف (أو أن العائلة متوترة). كيف أتخلّص من المرارة؟","أخشى أن أكون عبئًا على أولادي. كيف ينظر هذا المقطع إلى ذلك؟","يقول يسوع إن الذين يؤمنون به لهم الحياة الأبدية. ماذا يعني ذلك؟","صحتي تمنعني من الذهاب إلى الكنيسة. كيف أعبد الله في البيت؟","هل يتعارض تكريم الأجداد مع اتّباع يسوع؟ وكيف أكرّم والديّ الراحلين؟","كيف أشارك أصدقائي القدامى وجيراني صلاح يسوع؟","بعد أن أؤمن بيسوع، كيف ينبغي أن تُعاش الأيام العادية؟","أودّ أن أعتمد. ماذا ينبغي أن أستعد له؟","في نهاية العمر، كيف سيكون يسوع معي؟ وماذا تستطيع أسرتي أن تفعل؟","علّمني جملة سهلة أصلّي بها إلى يسوع كل يوم."],"single_parent":["أنا الأم والأب معًا وقد أنهكني التعب. كيف يساعدني يسوع؟","كثيرًا ما أشعر بأنني قصّرتُ في حق طفلي. كيف يعزّيني هذا المقطع؟","المال شحيح ولا أعرف كيف أصل إلى آخر الشهر. ما الرجاء الذي يقدّمه الكتاب المقدس؟","جرحني شريكي السابق جرحًا عميقًا ولا أستطيع أن أسامحه. كيف أتخلّى عن ذلك؟","يسألني ابني: «أين ذهب أبي (أو أمي)؟» كيف أجيبه؟","طفلي متقلّب المزاج أو متمرّد. كيف أستخدم الكتاب المقدس لأسير معه؟","كثيرًا ما أشعر بأن الناس ينظرون إليّ نظرة دونية أو يصنّفونني. كيف ينظر الله إليّ؟","مرض طفلي في منتصف الليل وأنا وحدي ومذعور. هل تنفع الصلاة؟","أشعر بالوحدة وليس لدي من أتحدث إليه. كيف يكون يسوع معي؟","هل ما زالت هناك فرصة للحب أو للزواج من جديد؟ وما الحكمة التي يقدّمها الكتاب المقدس؟","أنا غاضب من الله. لماذا تفكّكت أسرتي؟","في خضم هذا الانشغال، كيف أساعد طفلي على التعرّف إلى يسوع؟","كيف أعلّم طفلي أن يصلّي وأن يقرأ الكتاب المقدس دون أن أضغط عليه؟","العمل ورعاية الأولاد يستنزفانني. كيف أمنع الشعور بالذنب من أن يسحقني؟","أنا مطلَّق (أو مطلَّقة). هل ما زال الله يقبلني؟ وهل أنا مؤهَّل للإيمان بيسوع؟","أريد أن أبدأ من جديد. ما البداية الجديدة التي يستطيع يسوع أن يمنحني إياها؟","إلى من أستطيع أن ألجأ طلبًا للعون؟ وكيف تدعمني الكنيسة أو الجماعة الإيمانية؟","أخشى أن يكرّر طفلي أخطائي. كيف أمنحه الأمان؟","أحتاج اليوم إلى جملة واحدة فقط لأجتاز هذا اليوم. أعطني رجاءً من فضلك.","أريد أن أسلّم هذا البيت ليسوع. كيف أصلّي؟"],"single":["العيش وحيدًا يجعلني أشعر بالوحدة أحيانًا. كيف ينظر الله إلى وحدتي؟","أهلي يلحّون عليّ بالزواج وأشعر بالضغط. كيف أتعامل مع ذلك؟","أريد أن أتزوج لكنني لم ألتقِ الشخص المناسب. هل أعدّ الله لي شريكًا؟","جُرحتُ في الحب ولا أستطيع أن أثق من جديد. كيف أُشفى؟","هل يجوز أن أرتبط بشخص من ديانة مختلفة؟ ماذا يقول الكتاب المقدس؟","أهتمّ كثيرًا بكلام الناس وأشعر بأن البقاء دون زواج فشل. هل هذا صحيح؟","العمل لا يترك لي حياة خاصة. ما معنى الحياة؟","أنا بخير وحدي. فلماذا أحتاج إلى الله؟","كيف أعرف إن كان شخص ما مناسبًا لي؟ وما الحكمة في ذلك؟","أصارع الشهوة والمواد الضارة على الإنترنت. هل يستطيع يسوع أن يساعدني؟","أخاف أن أشيخ وحدي. ما الطمأنينة التي يقدّمها الكتاب المقدس؟","أصدقائي جميعًا متزوجون ولديهم أولاد. كيف أتجنّب الحسد والمقارنة؟","ماذا يريد الله مني في هذه المرحلة من حياتي العزباء؟","أشعر بخيبة أمل في الحب وفي الله. هل يمكنني أن أكون صريحًا معه؟","لستُ مسيحيًّا بعد. هل يجوز لي، وأنا أعزب، أن أتعرّف إلى يسوع؟","أريد أن أتبع يسوع لكنني أخشى أن تتغيّر حياتي كثيرًا. ماذا سأخسر؟","كيف أجد أصدقاء حقيقيين وأبني دائرة تدعمني؟","يساورني القلق من ألّا يحبّني أحد. كيف هو حبّ يسوع؟","لا أصدّق أن الحب غير المشروط موجود. ماذا أفعل بهذا الشعور؟","إن أردتُ أن أسلّم حياتي ليسوع، فكيف أبدأ؟"],"parent":["طفلي يكره الدراسة ويقضي يومه على الهاتف. أنا قلق، ماذا أفعل؟","طفلي يردّ عليّ بوقاحة وأفقد أعصابي. كيف يساعدني هذا المقطع؟","أنا وزوجي (أو زوجتي) نختلف في تربية الأولاد ونتشاجر. ماذا ينبغي أن نفعل؟","كيف أتحدث إلى طفلي عن يسوع دون أن أبدو واعظًا؟","يسألني طفلي: «أين الله؟» و«لماذا يموت الناس؟» كيف أجيبه؟","كثيرًا ما أصرخ في وجه طفلي وأندم بعد ذلك. هل سيغفر لي الله؟","أخشى أن يتعرّض طفلي للتنمّر أو أن يصادق رفقة سيئة. كيف أصلّي من أجله؟","درجات طفلي ضعيفة. كيف أتجنّب المقارنة وزيادة الضغط عليه؟","من الصعب التوفيق بين العمل والأسرة وأخشى أن يفوتني نموّ طفلي. ماذا أستطيع أن أفعل؟","طفلي مريض (أو من ذوي الاحتياجات الخاصة) وألوم نفسي. كيف ينظر الله إلى هذا؟","ابني المراهق لا يريد أن يتحدث إليّ. كيف أقترب منه من جديد؟","أنا نفسي لا أُحسن التصرف. كيف أكون قدوة؟","في البيت من لا يؤمن. كيف أعيش إيماني في البيت؟","كيف أحوّل الصلاة وقراءة الكتاب المقدس مع طفلي إلى عادة عائلية سعيدة؟","ابتعد طفلي عن الإيمان أو ترك الكنيسة. ماذا أستطيع أن أفعل؟","يسألني طفلي: «أنتَ تؤمن بيسوع، فهل يجب أن أؤمن أنا أيضًا؟» كيف أجيبه؟","كيف أعلّم طفلي مواجهة الفشل وخيبة الأمل؟","أريد أفضل حياة لطفلي. ماذا يقول الكتاب المقدس عن أهمّ ما في الأمر؟","إيماني أنا ضعيف. كيف أقود طفلي إلى التعرّف إلى يسوع؟","كيف أصلّي اليوم من أجل حياة طفلي كلها؟"],"couple":["نحن في خصام صامت بعد شجار. من ينبغي أن يبدأ بالكلام؟ ماذا يقول هذا المقطع؟","عيوب شريك حياتي صارت أصعب على الاحتمال. ماذا أفعل؟","كثيرًا ما نتشاجر بسبب المال. ما الحكمة التي يقدّمها الكتاب المقدس للزوجين؟","أنا عالق بين شريك حياتي وأهله. ماذا ينبغي أن أفعل؟","شريك حياتي لا يؤمن بيسوع. كيف أحبّه دون أن أضغط عليه؟","لم نتحدث حديثًا حقيقيًّا منذ زمن طويل. كيف نعيد التواصل؟","لقد جرحني. هل أستطيع حقًّا أن أسامح؟","أنهكتنا تربية الأولاد كلينا. كيف نتجنّب تفريغ توترنا في بعضنا؟","أشعر بأنني أعطي أكثر وأحمل في قلبي مرارة. ماذا يعلّمني يسوع؟","طباعنا مختلفة جدًّا. كيف يكمّل أحدنا الآخر بدل أن يستنزفه؟","لسنا معتادين على الصلاة معًا. كيف نبدأ؟","لسنا متفقين على المستقبل (الانتقال، العمل). كيف نصبح قلبًا واحدًا؟","فتر حبّنا. كيف نعيد إشعاله؟","أخاف ألّا نصمد. ما الرجاء الذي يقدّمه الكتاب المقدس للزواج؟","هل «الخضوع» يعني أن أطيع شريك حياتي طاعة عمياء؟","شريك حياتي مستغرق في العمل أو الهاتف أو الألعاب. كيف أعبّر عن مشاعري؟","نريد بيتًا يكون يسوع في مركزه. ما الخطوة الأولى؟","هل يستطيع يسوع حقًّا أن يغيّر زواجنا؟","واحد منا فقط يؤمن بيسوع. كيف نحترم أحدنا الآخر؟","ما صلاة صغيرة واحدة نستطيع أن نصليها معًا الليلة؟"],"pastor":["كيف أستخلص من هذا المقطع مخططًا واضحًا لعظة يوم الأحد؟","أنا منهك. كيف أخدم دون أن أحترق؟","زملائي في الخدمة مختلفون في الرأي. كيف أستخدم الكلمة لأقودنا إلى الوحدة؟","بعض الأعضاء يتركون الكنيسة أو أن العدد لا يزداد. كيف أتجنّب القلق والمقارنة؟","كيف أرعى صديقًا لم يؤمن بعد لكنه بدأ يحضر إلى الكنيسة؟","كيف أشارك الإنجيل بوضوح ولطف مع شخص لا يؤمن؟","كيف أجيب باحثًا عن الحق لديه اعتراضات قوية (من خلفية بوذية، أو ديانة شعبية، أو إلحادية)؟","كيف أُعدّ دعوة لقبول المسيح دون ممارسة الضغط على أحد؟","حياتي الروحية جافّة. كيف أستعيد قوّتي؟","كيف أتعامل مع الخلافات أو الانتقادات داخل الكنيسة؟","كيف أتلمذ المؤمنين الجدد من أول إيمانهم حتى النموّ؟","كيف أُعدّ زملاء في الخدمة وخلفاء لي؟","كيف أوازن بين الأسرة والخدمة دون إهمال أسرتي؟","كيف أصلّي من أجل شخص يحتضر وأعزّي أسرته؟","شخص يريد أن يعتمد. كيف أُعدّ صفّ المعمودية وشهادته؟","يُقال إن عظاتي عميقة جدًّا أو سطحية جدًّا. كيف أجد التوازن؟","كيف أقود دراسة كتابية في مجموعة صغيرة يمكن لغير المؤمنين أن ينضمّوا إليها؟","كيف أجيب عن أسئلة صعبة مثل: «لماذا يتألم الأخيار؟»","في زحمة الخدمة، كيف أحافظ على ترتيب: «الحياة أولًا، ثم العلاقات، ثم الخدمة أخيرًا»؟","أعطني خاتمة قصيرة أستخدمها اليوم لأقود الأعضاء في الصلاة."]};
P.Q20SK = {"buddhism":["أردّد التراتيل البوذية وآكل طعامًا نباتيًّا. هل يجب أن أتخلى عن هذا لأتبع يسوع؟","تعلّم البوذية أن المعاناة تأتي من التعلّق. كيف ينظر الكتاب المقدس إلى معاناة الإنسان؟","تعلّم البوذية مبدأ الكارما. بمَ تختلف «النعمة» في الكتاب المقدس عن قانون السبب والنتيجة؟","بمَ يختلف التناسخ عن تعليم الكتاب المقدس بأن للإنسان حياة واحدة ثم الدينونة؟","تعلّم البوذية المساواة والرحمة. هل يعلّم يسوع أيضًا محبة الآخرين؟","أتعبّد لبوذا طلبًا لطمأنينة القلب. بمَ يختلف السلام الذي يمنحه يسوع؟","بوذا ويسوع كلاهما معلّم، أليس كذلك؟ لماذا يصف يسوع نفسه بأنه المخلّص؟","تتحدث البوذية عن «التخلّي». كيف يعلّمنا الكتاب المقدس أن نتخلّى عن القلق والمرارة؟","مارستُ التأمل. بمَ تختلف الصلاة التأملية المسيحية؟","تؤكد البوذية على الجهد الذاتي. لماذا يقول الكتاب المقدس إننا نخلص بالنعمة لا بالأعمال؟","يقول الكتاب المقدس إن الله هو الخالق. بمَ يختلف هذا عن مفهومي «الفراغ» و«الاعتماد المتبادل»؟","أهلي جميعًا بوذيون. هل سيؤذيهم أن أتبع يسوع؟ وكيف أتحدث معهم؟","عندما يموت عزيز علينا نقوم بطقوس إهداء الأجر. كيف ينظر المسيحيون إلى الراحلين وإلى إحياء ذكراهم؟","فعلتُ كثيرًا من الأعمال الصالحة. لماذا يقول الكتاب المقدس إنني أحتاج إلى الخلاص؟","تقول البوذية إن في كل إنسان طبيعة بوذية. كيف ينظر الكتاب المقدس إلى طبيعة الإنسان والخطية؟","لماذا يستطيع موت يسوع أن يغفر خطاياي؟ وما علاقة ذلك بالكارما؟","هل «النيرفانا» هي نفسها «الحياة الأبدية» و«السماء» في الكتاب المقدس؟","هل يمكن لبوذي أن يتبع يسوع في الوقت نفسه؟ ولماذا يؤكد الكتاب المقدس على الإله الحقيقي الواحد؟","أريد أن أتعرّف إلى يسوع. أيّ كتاب أو مقطع ينبغي أن أقرأ أولًا؟","إن كنتُ مستعدًّا أن أجرّب الصلاة إلى يسوع، فما الجملة الأولى التي أستطيع أن أقولها؟"],"folk":["أسرتي تعبد الآلهة والأجداد. إن اتّبعتُ يسوع، فهل لن أستطيع فعل ذلك بعد الآن؟ ولماذا؟","أتعبّد للآلهة طلبًا للسلام والحماية. هل يستطيع يسوع أن يمنحني ذلك؟","يعلّم الكتاب المقدس إكرام الوالدين. هل يعني اتّباع يسوع أنني عاقّ؟","في عيد تشينغمينغ وشهر الأشباح نكرّم الأجداد. كيف يستطيع المسيحي أن يتذكّرهم ويُظهر لهم الاحترام؟","في مذبح بيتنا آلهة كثيرة. أيّها الحقيقي؟","قراءة الطالع، والتضرّع إلى تاي سوي، وتغيير الحظ. ماذا يقول الكتاب المقدس عن ذلك؟","هل الفنغ شوي والعرافة في المعبد دقيقان؟ وكيف يواجه الذين يتبعون يسوع المجهول؟","تجارتي متعثرة وصديق ينصحني بعبادة إله الثروة. كيف يساعدني يسوع؟","في البيت مريض ويقول الناس إنه يجب إقامة طقس استدعاء الروح أو استشارة أحد الآلهة. ماذا أفعل؟","أخاف أن أُغضب الآلهة فأُعاقَب. ماذا يحدث لهذا الخوف إن اتّبعتُ يسوع؟","والداي يعارضان ذهابي إلى الكنيسة. كيف أتحدث معهما دون أن أجرح مشاعرهما؟","ماذا يقول الكتاب المقدس عن ماتسو وغوان غونغ وأمثالهما؟ هل هم حقيقيون؟","لماذا إله حقيقي واحد فقط؟ هل كل الآلهة الأخرى باطلة؟","هل أقاربي الراحلون بخير في العالم الآخر؟ وماذا أستطيع أن أفعل من أجلهم؟","تعبّدتُ في معابد كثيرة. هل سيرفضني الله؟","أفراح عائلتي وجنائزها تتضمن طقوس عبادة. كيف أشارك دون حرج إن كنتُ أتبع يسوع؟","في بيتنا أصنام وتمائم. ماذا أفعل بها بعد أن أؤمن؟","هل يستطيع يسوع أن يحميني؟ وبمَ تختلف حمايته عن حماية الآلهة؟","أريد أن أتعرّف إلى يسوع. هل أذهب إلى الكنيسة أولًا، أم أقرأ الكتاب المقدس وحدي أولًا؟","أريد أن أصلّي إلى يسوع. هل أحتاج إلى بخور أو قرابين؟ وكيف أصلّي؟"],"yiguandao":["أنا نباتي وأقدّر تهذيب النفس والأعمال الصالحة. هل يجب أن أغيّر ذلك لأتبع يسوع؟","تقول طريقة ييغوانداو إن «الأديان الخمسة أصلها واحد». فلماذا يقول يسوع إنه الطريق الوحيد؟","نحن نعبد «السماء». هل «الله» في الكتاب المقدس هو نفسه؟","تتحدث ييغوانداو عن تهذيب الطريق حتى يصير المرء قدّيسًا. هل «الخلاص» بالجهد أم بالنعمة؟","يعلّم معبدنا عن عصور الكوارث الثلاثة. ماذا يقول الكتاب المقدس عن النهاية والدينونة؟","هل الصلاة إلى يسوع تحتاج إلى طقوس؟ وبمَ تختلف عن طريقتنا في تكريم السماء؟","هل يسوع الذي في الكتاب المقدس هو نفسه يسوع الذي في معبدنا (أحد الحكماء الخمسة)؟","أنا منخرط بعمق في معبدنا. إن تعرّفتُ إلى يسوع، فهل أخون معلّميّ وإخوتي في الإيمان؟","إخوتي في الإيمان أناس طيبون. فلماذا يقول الكتاب المقدس إن الجميع خطاة ويحتاجون إلى مخلّص؟","نتحدث عن «الربّ العلي» و«العودة إلى السماء». ما هي السماء والحياة الأبدية في الكتاب المقدس؟","نسعى إلى الطريق ونحرق البخور. كيف تبدو العبادة في الكتاب المقدس؟","لماذا يقول الكتاب المقدس إن يسوع هو ابن الله؟ وبمَ يختلف هذا عن إنسان يهذّب نفسه حتى يصير إلهًا؟","أسرتي كلها في المعبد. كيف أخبرهم أنني أريد أن أفهم يسوع؟","تقدّر ييغوانداو برّ الوالدين والأخلاق. ماذا يعلّم الكتاب المقدس عن الأسرة؟","في معبدنا «طلب الطريق» و«المعلّم الناقل». أما اتّباع يسوع ففيه المعمودية. فما الفرق؟","شعرتُ يومًا بالسلام في المعبد. بمَ يختلف السلام الذي يمنحه يسوع؟","ماذا تساوي ممارستي السابقة وأعمالي الصالحة أمام الله؟","لدي شكوك لكنني أخشى أن يُقال إن إيماني ضعيف. هل يجوز أن أسأل بصدق؟","أريد أن أتعرّف إلى يسوع. من أي جزء في الكتاب المقدس يحسن أن أبدأ؟","إن صلّيتُ إلى يسوع، فهل يجب أن أترك المعبد أولًا؟ وما الجملة الأولى التي أستطيع أن أقولها؟"],"muslim":["أؤمن بأن الله واحد. أليس إيمان المسيحيين بـ«الثالوث» إيمانًا بثلاثة آلهة؟","نحن نُكرم عيسى (يسوع). فلماذا يقول الكتاب المقدس إنه ابن الله؟","يذكر القرآن والكتاب المقدس كلاهما إبراهيم وموسى. فبمَ يختلفان؟","يرجو المسلمون الجنة بأركان الإسلام والأعمال الصالحة. فلماذا يقول الكتاب المقدس إن الخلاص بالنعمة؟","هل صُلب عيسى حقًّا ومات؟ ولماذا كان موته ضروريًّا؟","يقول بعضهم إن الكتاب المقدس قد حُرِّف. فهل هو موثوق؟ وما الدليل؟","ما الأدلة التاريخية على قيامة عيسى؟","أصلّي خمس مرات في اليوم. فكيف يصلّي المسيحيون؟ وهل يجب أن تكون الصلاة بصيغة ثابتة؟","لقد أخطأتُ. كيف يغفر الله بحسب تقليدي؟ وما هو الغفران في الكتاب المقدس؟","إن اهتممتُ بعيسى، فكيف ستنظر أسرتي ومجتمعي إلى ذلك؟ وكيف أحافظ على نفسي وعلى صلاتي بأهلي؟","هل يمكنني أن أقرأ الكتاب المقدس وحده لأتعرّف إلى عيسى، دون أن أجادل أهلي؟","ماذا يقول الكتاب المقدس عن هوية عيسى؟ أهو نبيّ فقط، أم أكثر من ذلك؟","يقول الكتاب المقدس إن الله محبة. وأنا أعرف رحمة الله جيدًا. فما أوجه الشبه والاختلاف؟","هل يشرب المسيحيون الخمر أو يأكلون لحم الخنزير؟ ماذا يعلّم الكتاب المقدس عن الطعام؟","في يوم الدينونة، كيف أتأكد من أنني سأنجو؟","ماذا يعني «الكلمة صار جسدًا»؟ كيف يمكن أن يصير الله إنسانًا؟","كيف ينظر المسيحيون إلى الحرب المقدسة والعنف؟ وكيف علّم عيسى الناس أن يعاملوا أعداءهم؟","نشأتُ مسلمًا. فإن اتّبعتُ عيسى، فهل يُعدّ ذلك خيانة؟","كيف أقرأ إنجيل يوحنا بهدوء لأتعرّف إلى عيسى؟","إن أردتُ أن أصلّي إلى عيسى، فهل يجوز أن أستخدم كلماتي الخاصة؟ وما الجملة الأولى؟"],"atheist":["يستطيع العلم أن يفسّر أصل الكون. فلماذا ما زلنا نحتاج إلى الله؟","هل تتعارض نظرية التطور مع الخلق كما في الكتاب المقدس؟","لم أرَ الله قط. ما الدليل على وجوده؟","إن كان الله قادرًا على كل شيء ومحبًّا، فلماذا توجد الحروب والأمراض والكوارث؟","الأخلاق لا تحتاج إلى دين. فلماذا ما زلنا نحتاج إلى الإيمان؟","في التاريخ حملات صليبية وحروب دينية. أليست هذه مشكلة الإيمان؟","تبدو بعض قصص الكتاب المقدس (مثل المعجزات) غير معقولة. كيف ينبغي أن أقرأها؟","هل وُجد يسوع فعلًا في التاريخ؟ وما السجلات التاريخية التي تشهد بذلك؟","ما الأساس التاريخي للقيامة؟ أليست من اختلاق التلاميذ؟","أليس الإيمان مجرّد عزاء نفسي وهروب من الواقع؟","أليس أبسط أن يكون الموت هو النهاية؟ فلماذا الحديث عن الحياة الأبدية؟","من دون الله، من أين يأتي معنى الحياة؟","كيف يواجه المسيحيون شكوكهم وأسئلتهم؟ وهل يجوز لي أن أطرحها؟","رأيتُ مسيحيين لا تتطابق أقوالهم مع أفعالهم. أليس هذا دليلًا على بطلان الإيمان؟","أليس «الإيمان» يعني التوقف عن التفكير؟","إن أردتُ أن أنظر إلى يسوع بجدّية، فما الموقف الذي ينبغي أن أتخذه وما الذي أقرأه أولًا؟","هل الصلاة تنفع حقًّا؟ وهل هناك طريقة أختبر بها ذلك بنفسي؟","لماذا يقول الكتاب المقدس إن للإنسان «خطية»؟ لا أظن أنني ارتكبتُ شيئًا فظيعًا.","ما الذي يتميّز به تعليم يسوع ويستحق أن يؤخذ بجدّية؟","ما زلتُ أشك، لكنني مستعد أن أجرّب الصلاة مرة واحدة. ماذا أقول؟"]};
function cnt(n, one, two, few, many){ n = +n; return n===1 ? one : n===2 ? two : (n>=3 && n<=10) ? n+' '+few : n+' '+many; }
function cDay(n){ return cnt(n,'يوم واحد','يومان','أيام','يومًا'); }
P.rules = [
 [/^(Sun|Mon|Tue|Wed|Thu|Fri|Sat)$/, function(m){ return WD[m[1]]; }],
 [/^in (\d+) min$/, function(m){ return 'بعد ' + (+m[1]===2 ? 'دقيقتين' : +m[1]===1 ? 'دقيقة واحدة' : cnt(m[1],'','','دقائق','دقيقة')); }],
 [/^in (\d+) hr(?: (\d+) min)?$/, function(m){ return 'بعد ' + (+m[1]===2 ? 'ساعتين' : +m[1]===1 ? 'ساعة واحدة' : cnt(m[1],'','','ساعات','ساعة')) + (m[2] ? ' و' + (+m[2]===2 ? 'دقيقتين' : +m[2]===1 ? 'دقيقة' : cnt(m[2],'','','دقائق','دقيقة')) : ''); }],
 [/^in (\d+) days?(?: (\d+) hr)?$/, function(m){ return 'بعد ' + (+m[1]===2 ? 'يومين' : +m[1]===1 ? 'يوم واحد' : cnt(m[1],'','','أيام','يومًا')) + (m[2] ? ' و' + (+m[2]===2 ? 'ساعتين' : +m[2]===1 ? 'ساعة' : cnt(m[2],'','','ساعات','ساعة')) : ''); }],
 [/^You finished the whole book of (.+)!$/, function(m){ return 'لقد أنهيتَ قراءة ' + m[1] + ' بالكامل!'; }],
 [/^(.+) — cleared!$/, function(m){ return m[1] + ' — اكتمل!'; }],
 [/^Wow! You finished (.+)! 🎉$/, function(m){ return 'رائع! لقد أنهيتَ ' + m[1] + '! 🎉'; }],
 [/^Medal (\d+) · (\d+) chapters$/, function(m){ return 'الميدالية ' + m[1] + ' · ' + cnt(m[2],'إصحاح واحد','إصحاحان','إصحاحات','إصحاحًا'); }],
 [/^(\d+) days ago$/, function(m){ return 'منذ ' + (+m[1]===2 ? 'يومين' : +m[1]===1 ? 'يوم' : cnt(m[1],'','','أيام','يومًا')); }],
 [/^Reading “(.+)”; has not started this plan$/, function(m){ return 'يقرأ «' + m[1] + '»؛ ولم يبدأ هذه الخطة'; }],
 [/^They are (\d+) day\(s\) ahead; catch up together$/, function(m){ return 'هو متقدّم عليك بمقدار ' + (+m[1]===2 ? 'يومين' : +m[1]===1 ? 'يوم واحد' : cnt(m[1],'','','أيام','يومًا')) + '؛ هيّا نلحق به معًا'; }],
 [/^You are (\d+) day\(s\) ahead; encourage them$/, function(m){ return 'أنت متقدّم عليه بمقدار ' + (+m[1]===2 ? 'يومين' : +m[1]===1 ? 'يوم واحد' : cnt(m[1],'','','أيام','يومًا')) + '؛ شجّعه'; }],
 [/^Volume (\d+)$/, function(m){ return 'المجلد ' + m[1]; }],
 [/^✗ Font failed to load \((.*)\)\. Check the network and tap the font button again\.$/, function(m){ return '✗ تعذّر تحميل الخط (' + m[1] + '). تحقّق من الشبكة ثم اضغط زر الخط مرة أخرى.'; }],
 [/^Could not open the camera \((.*)\)\.$/, function(m){ return 'تعذّر فتح الكاميرا (' + (m[1] === 'unknown' ? 'سبب غير معروف' : m[1]) + ').'; }],
 [/^Congratulations — you finished the whole book of (.+)!$/, function(m){ return 'تهانينا — لقد أنهيتَ قراءة ' + m[1] + ' بالكامل!'; }],
 [/^  Points (\d+) \/ (\d+)$/, function(m){ return '  النقاط ' + m[1] + ' / ' + m[2]; }],
 [/^Review missed \((\d+)\)$/, function(m){ return 'مراجعة الأسئلة الخاطئة (' + m[1] + ')'; }],
 [/^The answer is a (.+)$/, function(m){ return 'الإجابة هي «' + m[1] + '»'; }],
 [/^Worth (\d+) points? now — fewer hints, more points$/, function(m){ return 'تساوي الآن ' + (+m[1]===2 ? 'نقطتين' : +m[1]===1 ? 'نقطة واحدة' : cnt(m[1],'','','نقاط','نقطة')) + ' — كلما قلّت التلميحات زادت النقاط'; }],
 [/^Yes \(\+(\d+)\)$/, function(m){ return 'نعم (+' + m[1] + ')'; }],
 [/^I got (\d+) \/ (\d+) on the (quiz|riddles) for (.+)!$/, function(m){ return 'حصلتُ على ' + m[1] + ' / ' + m[2] + ' في ' + (m[3] === 'quiz' ? 'اختبار' : 'ألغاز') + ' «' + m[4] + '» في 321 الكتاب المقدس التفاعلي!'; }],
 [/^(\d+) riddles — hints appear one by one; guess early for more points$/, function(m){ return cnt(m[1],'لغز واحد','لغزان','ألغاز','لغزًا') + ' — تظهر التلميحات واحدًا تلو الآخر؛ وكلما خمّنتَ مبكرًا نلتَ نقاطًا أكثر'; }],
 [/^(\d+) multiple-choice questions with instant explanations; misses go to your notebook$/, function(m){ return cnt(m[1],'سؤال','سؤالان','أسئلة','سؤالًا') + ' اختيار من متعدد مع شرح فوري؛ والأسئلة الخاطئة تُسجَّل في دفترك'; }],
 [/^(\d+) missed questions to review$/, function(m){ return cnt(m[1],'سؤال خاطئ','سؤالان خاطئان','أسئلة خاطئة','سؤالًا خاطئًا') + ' للمراجعة'; }]
];

P.dict[' and writing your questions…'] = " ويكتب أسئلتك…";
P.dict["Very short"] = "قصير جدًا";
P.dict["Short"] = "قصير";
